style.content:
:root {
  --bg: #080b10;
  --panel: #111923;
  --panel2: #192432;
  --red: #d93643;
  --white: #f3f5f7;
  --muted: #9ba8b6;
  --border: #293847;
  --green: #52c58d;
  --gold: #d8b36d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}

body {
  background: var(--bg);
  color: var(--white);
  font-family: 'Inter', sans-serif;
}

button, input {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

.app {
  overflow: hidden;
}

.hidden {
  display: none !important;
}

/* HEADER */

.navbar {
  min-height: 74px;
  padding: 0 7%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  position: sticky;
  top: 0;
  z-index: 20;
  background: rgba(8,11,16,.97);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(12px);
}

.logo {
  font-size: 28px;
  font-weight: 900;
  letter-spacing: -2px;
}

.logo span {
  color: var(--red);
}

.logo small {
  display: block;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 2px;
}

.navbar nav {
  display: flex;
  gap: 22px;
}

.navbar nav a {
  font-size: 12px;
  color: #c1cbd5;
  transition: .2s;
}

.navbar nav a:hover {
  color: var(--red);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.outline-btn {
  color: white;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 10px 15px;
}

.outline-btn:hover {
  color: var(--red);
  border-color: var(--red);
}

.menu-btn {
  display: none;
  background: transparent;
  border: 0;
  color: white;
  font-size: 24px;
}

/* HERO */

.hero {
  min-height: 550px;
  padding: 90px 10%;
  display: flex;
  align-items: center;
  position: relative;
  background:
    linear-gradient(
      90deg,
      rgba(5,9,14,.97),
      rgba(5,9,14,.82) 58%,
      rgba(5,9,14,.4)
    ),
    url("https://images.unsplash.com/photo-1453873531674-2151bcd01707?auto=format&fit=crop&w=1800&q=85")
    center/cover;
}

.hero-content {
  max-width: 660px;
}

.tag,
.eyebrow {
  color: var(--red);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2px;
}

.hero h1 {
  margin: 24px 0;
  font-size: clamp(44px,7vw,78px);
  line-height: 1.06;
  letter-spacing: -3px;
}

.hero h1 span {
  color: var(--red);
}

.hero p {
  color: #c4ccd5;
  font-size: 14px;
  line-height: 1.9;
  max-width: 540px;
  margin-bottom: 28px;
}

.main-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 20px;
  background: var(--red);
  color: white;
  border: 1px solid var(--red);
  border-radius: 3px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
  transition: .2s;
}

.main-btn:hover {
  color: var(--red);
  background: transparent;
  transform: translateY(-2px);
}

.main-btn:disabled {
  opacity: .4;
  cursor: not-allowed;
  transform: none;
}

.hero-stamp {
  position: absolute;
  right: 10%;
  bottom: 55px;
  width: 120px;
  height: 120px;
  border: 1px solid #b84a54;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #f0a2a8;
  transform: rotate(-12deg);
}

.hero-stamp strong {
  font-size: 38px;
  color: var(--red);
}

.hero-stamp span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 2px;
}

.hero-stamp small {
  font-size: 8px;
  margin-top: 5px;
}

/* STATS */

.stats {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  padding: 24px 12%;
  background: #101722;
  border-block: 1px solid var(--border);
}

.stats div {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  border-right: 1px solid var(--border);
}

.stats div:last-child {
  border: 0;
}

.stats strong {
  font-size: 28px;
  color: var(--red);
}

.stats span {
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 2px;
}

/* SECTIONS */

.section {
  padding: 80px 8%;
}

.section-heading {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 20px;
  margin-bottom: 32px;
}

.section-heading h2,
.about-section h2 {
  margin-top: 12px;
  font-size: clamp(27px,4vw,40px);
}

.case-count {
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 1.5px;
}

/* CASE CARDS */

.case-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 20px;
}

.case-card {
  background: var(--panel);
  border: 1px solid var(--border);
  transition: .25s;
}

.case-card:hover {
  transform: translateY(-5px);
  border-color: var(--red);
}

.case-image {
  height: 185px;
  position: relative;
  background-size: cover;
  background-position: center;
}

.case-image::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg,rgba(0,0,0,.75),transparent 70%);
}

.case-image span {
  position: absolute;
  z-index: 1;
  left: 16px;
  bottom: 14px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2px;
}

.image-one {
  background-image: url("https://images.unsplash.com/photo-1561214115-f2f134cc4912?auto=format&fit=crop&w=900&q=80");
}

.image-two {
  background-image: url("https://images.unsplash.com/photo-1507842217343-583bb7270b66?auto=format&fit=crop&w=900&q=80");
}

.image-three {
  background-image: url("https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=900&q=80");
}

.case-info {
  padding: 22px;
}

.case-status {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #e4a1a7;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
}

.case-status i,
.status-dot {
  width: 7px;
  height: 7px;
  display: inline-block;
  background: var(--red);
  border-radius: 50%;
  box-shadow: 0 0 9px var(--red);
}

.case-info h3 {
  font-size: 19px;
  margin: 14px 0 10px;
}

.case-info p {
  min-height: 70px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.8;
}

.case-btn {
  width: 100%;
  text-align: left;
  margin-top: 18px;
  padding-top: 13px;
  background: transparent;
  color: #ef727b;
  border: 0;
  border-top: 1px solid var(--border);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.case-btn:hover {
  color: white;
}

/* INVESTIGATION FILE */

.investigation-panel {
  margin-top: 38px;
  padding: 28px;
  background: linear-gradient(145deg,#141e2a,#0c121a);
  border: 1px solid #3a4a5a;
  border-top: 3px solid var(--red);
  box-shadow: 0 20px 70px #0007;
  scroll-margin-top: 90px;
  animation: appear .3s ease;
}

@keyframes appear {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.file-header {
  display: flex;
  justify-content: space-between;
  gap: 15px;
}

.file-header h2 {
  font-size: clamp(23px,4vw,35px);
  margin: 10px 0 7px;
}

.file-header p {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 2px;
}

.close-investigation {
  width: 38px;
  height: 38px;
  background: #202d3b;
  color: white;
  border: 1px solid #465566;
  border-radius: 3px;
}

.close-investigation:hover {
  background: var(--red);
}

.file-stamp-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 22px;
  padding: 14px;
  margin: 23px 0;
  background: #090e15;
  border: 1px solid var(--border);
  color: #bac6d2;
  font-size: 9px;
}

.file-stamp-row b {
  color: white;
}

.report-section,
.decision-section {
  padding: 21px;
  margin-top: 16px;
  background: rgba(5,9,14,.5);
  border: 1px solid var(--border);
}

.section-label {
  display: block;
  color: #ed737d;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.4px;
  margin-bottom: 15px;
}

.report-section > p {
  color: #d0d8e1;
  font-size: 13px;
  line-height: 2;
}

.scene-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 11px;
}

.scene-item {
  padding: 14px;
  background: #172331;
  border-left: 2px solid var(--gold);
}

.scene-item strong {
  display: block;
  color: var(--gold);
  font-size: 10px;
  margin-bottom: 8px;
}

.scene-item p {
  color: #c7d0da;
  font-size: 12px;
  line-height: 1.8;
}

.report-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.timeline-list,
.evidence-list,
.records-list {
  display: grid;
  gap: 10px;
}

.timeline-item {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 12px;
  padding: 11px;
  background: #172330;
  border-left: 2px solid var(--red);
}

.timeline-time {
  color: #ee858d;
  font-size: 11px;
  font-weight: 800;
}

.timeline-text {
  color: #cbd4de;
  font-size: 12px;
  line-height: 1.7;
}

.evidence-item {
  display: flex;
  align-items: start;
  gap: 11px;
  padding: 12px;
  background: #172330;
  border: 1px solid #2c3c4c;
}

.evidence-number {
  flex: 0 0 25px;
  height: 25px;
  display: grid;
  place-items: center;
  background: #48242a;
  color: #ffb1b6;
  font-size: 10px;
  font-weight: 800;
}

.evidence-item p {
  color: #cbd4de;
  font-size: 12px;
  line-height: 1.8;
}

.record-item {
  padding: 12px;
  background: #172330;
  border-left: 2px solid #6888a8;
}

.record-item strong {
  display: block;
  color: #a8c9e7;
  font-size: 10px;
  margin-bottom: 7px;
}

.record-item p {
  color: #cbd4de;
  font-size: 12px;
  line-height: 1.8;
}

.suspect-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 12px;
}

.suspect-card {
  padding: 16px;
  background: #172330;
  border: 1px solid #354454;
}

.suspect-id {
  color: #ed737d;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
}

.suspect-card h4 {
  font-size: 17px;
  margin: 10px 0 5px;
}

.suspect-role {
  font-size: 10px;
  color: var(--gold);
  margin-bottom: 12px;
}

.suspect-card p {
  font-size: 12px;
  color: #cbd4de;
  line-height: 1.9;
}

.decision-section h3 {
  font-size: 19px;
  line-height: 1.7;
  margin-bottom: 9px;
}

.decision-section > p {
  font-size: 12px;
  color: var(--muted);
  line-height: 1.8;
  margin-bottom: 16px;
}

/* ANSWERS */

.answers {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 11px;
}

.answer-btn {
  padding: 14px;
  color: #edf1f5;
  text-align: left;
  background: #182431;
  border: 1px solid #37495a;
  border-radius: 3px;
  transition: .2s;
}

.answer-btn:hover:not(:disabled) {
  border-color: var(--red);
  background: #2a1c23;
}

.answer-btn.correct {
  background: #153528;
  border-color: var(--green);
}

.answer-btn.wrong {
  background: #3b1d23;
  border-color: var(--red);
}

.answer-btn:disabled {
  cursor: default;
}

.feedback {
  min-height: 25px;
  margin-top: 15px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.9;
}

.feedback.good {
  color: #75d9a6;
}

.feedback.bad {
  color: #ff858c;
}

/* RIDDLES */

.riddles-section {
  background: #0d131b;
}

.riddle-box {
  max-width: 850px;
  margin: auto;
  padding: 30px;
  background: var(--panel);
  border: 1px solid var(--border);
}

.riddle-top {
  display: flex;
  justify-content: space-between;
  color: var(--red);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.5px;
}

.riddle-top span:last-child {
  color: var(--muted);
}

.riddle-box h3 {
  font-size: 19px;
  line-height: 1.9;
  margin: 25px 0;
}

.riddle-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 18px;
}

.hint-text {
  color: var(--gold);
  font-size: 12px;
  line-height: 1.8;
  margin-top: 14px;
}

/* SECRET ARCHIVE */

.vault-section {
  background: radial-gradient(ellipse at top,#241116 0%,#080b10 70%);
}

.vault-access {
  max-width: 520px;
  margin: auto;
  padding: 32px;
  background: #111923;
  border: 1px solid #563039;
  text-align: center;
}

.vault-icon {
  font-size: 45px;
  margin-bottom: 14px;
}

.vault-access h3 {
  margin-bottom: 12px;
  letter-spacing: 2px;
}

.vault-access > p {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.8;
}

.vault-access form {
  display: grid;
  gap: 12px;
  margin-top: 20px;
}

.vault-access input {
  width: 100%;
  padding: 15px;
  color: white;
  background: #080c12;
  border: 1px solid #3a4857;
  outline: none;
  text-align: center;
  letter-spacing: 8px;
  border-radius: 3px;
}

.vault-access input:focus {
  border-color: var(--red);
}

.vault-access .main-btn {
  width: 100%;
}

.vault-grid {
  display: none;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 15px;
  margin-top: 30px;
}

.vault-grid.visible {
  display: grid;
}

.vault-card {
  padding: 22px;
  background: #111923;
  border: 1px solid var(--border);
  border-top: 2px solid var(--red);
}

.vault-card h3 {
  font-size: 13px;
  color: #f07881;
  margin-bottom: 13px;
}

.vault-card p {
  font-size: 12px;
  line-height: 1.9;
}

.archive-question {
  color: #e0e5eb;
}

.archive-answer {
  margin-top: 13px;
  padding: 12px;
  color: #80dfad;
  background: #132b20;
  border: 1px solid #28553d;
}

.archive-explanation {
  margin-top: 12px;
  color: #aeb9c4;
}

/* ABOUT + FOOTER */

.about-section {
  padding: 85px 9%;
  text-align: center;
  background: radial-gradient(ellipse at center,#201116,#080b10 70%);
}

.about-section p {
  max-width: 670px;
  margin: 20px auto 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 2;
}

footer {
  padding: 28px 7%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  border-top: 1px solid var(--border);
}

footer p,
.footer-credit {
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 1px;
}

.footer-credit {
  color: #e06a73;
}

/* ARABIC / RTL */

[dir="rtl"] body,
[dir="rtl"] .app {
  font-family: 'Cairo', sans-serif;
}

[dir="rtl"] .hero h1 {
  letter-spacing: 0;
  line-height: 1.3;
}

[dir="rtl"] .case-image span {
  left: auto;
  right: 16px;
}

[dir="rtl"] .case-btn,
[dir="rtl"] .answer-btn {
  text-align: right;
}

[dir="rtl"] .scene-item,
[dir="rtl"] .record-item {
  border-left: 0;
  border-right: 2px solid var(--gold);
}

[dir="rtl"] .timeline-item {
  border-left: 0;
  border-right: 2px solid var(--red);
}

[dir="rtl"] .evidence-item {
  text-align: right;
}

/* MOBILE */

@media(max-width:900px) {
  .navbar {
    padding: 0 5%;
  }

  .navbar nav {
    gap: 13px;
  }

  .hero {
    padding: 80px 7%;
  }

  .section {
    padding: 70px 6%;
  }

  .case-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }
}

@media(max-width:680px) {
  .navbar {
    min-height: 66px;
  }

  .menu-btn {
    display: block;
  }

  .navbar nav {
    display: none;
    position: absolute;
    top: 66px;
    left: 0;
    right: 0;
    padding: 20px;
    background: #111923;
    border-bottom: 1px solid var(--border);
    flex-direction: column;
    gap: 18px;
  }

  .navbar nav.open {
    display: flex;
  }

  .hero {
    min-height: 480px;
    padding: 60px 7%;
  }

  .hero-stamp {
    display: none;
  }

  .hero h1 {
    letter-spacing: -1px;
  }

  .stats {
    padding: 20px 2%;
  }

  .stats strong {
    font-size: 22px;
  }

  .stats span {
    font-size: 8px;
    letter-spacing: .5px;
  }

  .case-grid,
  .report-columns,
  .scene-grid,
  .suspect-grid,
  .vault-grid {
    grid-template-columns: 1fr;
  }

  .section-heading {
    align-items: start;
  }

  .case-count {
    display: none;
  }

  .investigation-panel {
    padding: 15px;
  }

  .report-section,
  .decision-section {
    padding: 15px;
  }

  .answers {
    grid-template-columns: 1fr;
  }

  .riddle-box {
    padding: 20px;
  }

  .riddle-footer {
    flex-direction: column;
  }

  .riddle-footer button {
    width: 100%;
  }

  footer {
    flex-direction: column;
    text-align: center;
  }
}

@media(prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation: none !important;
    transition: none !important;
  }
}

script.content:
"use strict";

// ======================================
// THE MYSTERY ROOM
// HTML + CSS + JAVASCRIPT
// Arabic / English
// ======================================

const $ = id => document.getElementById(id);

let language = "en";
let score = 0;
let solved = 0;
let currentRiddle = 0;
let riddleAnswered = false;
let currentCase = null;
let archiveUnlocked = false;

const solvedCases = new Set();
const solvedRiddles = new Set();


// ======================================
// LANGUAGE HELPER
// Every bilingual text is an object:
// { en: "English", ar: "Arabic" }
// ======================================

function tr(value) {
  if (!value || typeof value !== "object") {
    return "";
  }

  return value[language] ?? "";
}

function makeElement(tag, className, content) {
  const element = document.createElement(tag);

  if (className) {
    element.className = className;
  }

  if (content !== undefined) {
    element.textContent = content;
  }

  return element;
}


// ======================================
// POLICE CASE DATABASE
// ======================================

const cases = {

  compass: {
    id: "TMR-2026-001",

    title: {
      en: "THE MISSING COMPASS",
      ar: "البوصلة المفقودة"
    },

